const TIER = 'pro';

// --- shared helpers (inlined by the builder into every Code node that needs them) ---
const MULTI_TLD = ['co.uk', 'org.uk', 'ac.uk', 'gov.uk', 'com.au', 'net.au', 'org.au', 'co.nz', 'co.jp', 'co.kr', 'com.br', 'co.za', 'com.sg', 'co.in', 'com.mx', 'com.tr', 'co.il'];

function hostOf(u) {
  try { return new URL(String(u)).hostname.toLowerCase().replace(/^www\./, ''); } catch (e) { return ''; }
}

function registrable(hostOrUrl) {
  const raw = String(hostOrUrl || '');
  const h = /^https?:\/\//i.test(raw) ? hostOf(raw) : raw.toLowerCase().replace(/^www\./, '').split('/')[0];
  const parts = h.split('.').filter(Boolean);
  if (parts.length <= 2) return h;
  const last2 = parts.slice(-2).join('.');
  return MULTI_TLD.indexOf(last2) === -1 ? last2 : parts.slice(-3).join('.');
}

function normalizeUrl(u) {
  try {
    const url = new URL(String(u));
    if (url.protocol !== 'http:' && url.protocol !== 'https:') return '';
    url.hash = '';
    url.hostname = url.hostname.toLowerCase().replace(/^www\./, '');
    const drop = [];
    url.searchParams.forEach((_v, k) => { if (/^(utm_|fbclid|gclid|mc_|msclkid|igshid|ref$|source$)/i.test(k)) drop.push(k); });
    drop.forEach((k) => url.searchParams.delete(k));
    let s = url.toString().replace(/\?$/, '');
    if (url.pathname !== '/') s = s.replace(/\/$/, '');
    return s;
  } catch (e) { return ''; }
}

function normWs(s) { return String(s === null || s === undefined ? '' : s).replace(/\s+/g, ' ').trim(); }

function slugName(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ''); }

function canonical(v) {
  if (v === null || typeof v !== 'object') return JSON.stringify(v === undefined ? null : v);
  if (Array.isArray(v)) return '[' + v.map(canonical).join(',') + ']';
  return '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + canonical(v[k])).join(',') + '}';
}

// FNV-1a style 64-bit-ish hash rendered as 16 hex chars. Pure JS on purpose: n8n Code nodes
// cannot require('crypto') unless the instance sets NODE_FUNCTION_ALLOW_BUILTIN, and a giveaway
// workflow must not depend on an instance env var.
function stableHash(value) {
  const s = typeof value === 'string' ? value : canonical(value);
  let h1 = 0x811c9dc5;
  let h2 = 0x1000193;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 16777619) >>> 0;
    h2 = Math.imul(h2 + c, 2654435761) >>> 0;
  }
  return h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0');
}

// geo-<run_id>-<sku>-<bodyHash>. Computed here as a data field, never as an inline expression on
// the HTTP node: an inline expression is re-evaluated on retry, a data field is not.
function idemKey(runId, sku, body) { return 'geo-' + runId + '-' + sku + '-' + stableHash(body); }

function safeAll(name) { try { return $(name).all(); } catch (e) { return []; } }

function safeFirst(name) { const a = safeAll(name); return a.length ? a[0].json : null; }

// Every AnyAPI call is sent with fullResponse + neverError, so the workflow can tell an empty
// answer (200 found:false, charged) from a failure (>=400) instead of guessing from an error item.
function httpStatus(item) { const j = item && item.json ? item.json : item; return Number(j && j.statusCode) || 0; }
function httpBody(item) { const j = item && item.json ? item.json : item; return (j && j.body) || {}; }
function httpOk(item) { const s = httpStatus(item); return s >= 200 && s < 300; }
function httpCost(item) { return httpOk(item) ? Number(httpBody(item).costUsd || 0) : 0; }
function httpFound(item) { const o = httpBody(item).output || {}; return o.found === true; }
function httpData(item) { const o = httpBody(item).output || {}; return o.data || null; }
function httpErrorCode(item) {
  const b = httpBody(item);
  const e = b && b.error;
  if (e && typeof e === 'object') return String(e.code || e.message || 'error');
  if (typeof b === 'string') return b.slice(0, 200);
  return String((b && b.code) || httpStatus(item) || 'error');
}

// Turns the form submission into the one config item every later band reads by node name.
// Throws on anything the run cannot recover from, so a bad submission fails here and not after
// the first paid call.

// Seed list of pages you cannot pitch an author on. Review platforms list you through their own
// vendor flow; on social and UGC platforms there is no editor to pitch. Edit it on the form.
const DEFAULT_BLOCKED = [
  'reddit.com', 'quora.com', 'wikipedia.org', 'youtube.com', 'linkedin.com', 'facebook.com',
  'x.com', 'twitter.com', 'instagram.com', 'medium.com', 'news.ycombinator.com', 'amazon.com',
  'g2.com', 'capterra.com', 'trustpilot.com', 'getapp.com', 'softwareadvice.com', 'producthunt.com',
];

const form = $input.first().json;
const runId = String($execution.id);
const lines = (v) => String(v || '').split(/[\n,]/).map((s) => s.trim()).filter(Boolean);
const need = (v, label) => {
  const s = String(v === null || v === undefined ? '' : v).trim();
  if (!s) throw new Error('Missing required field: ' + label);
  return s;
};
const positive = (v, label) => {
  const n = Number(v);
  if (!Number.isFinite(n) || n <= 0) throw new Error(label + ' must be a positive number');
  return n;
};

let website = need(form.website, 'Your website URL');
if (!/^https?:\/\//i.test(website)) website = 'https://' + website;
const brandDomain = registrable(website);
if (!brandDomain) throw new Error('Could not read a domain out of: ' + website);

const brand = need(form.brand, 'Your brand name');
const competitors = lines(form.competitors);
if (competitors.length === 0) throw new Error('List at least one competitor, one per line');

const blocked = lines(form.blocked_domains).map(registrable).filter(Boolean);

// A link inside the offer would be a URL the pitch gate has to refuse on every single draft, and
// the operator would only find out by reading a run's worth of identical rejections. Refuse it here
// where the reason is one line and the run has not spent anything yet.
const reciprocity = String(form.reciprocity || '').trim().replace(/\s+/g, ' ');
if (/https?:\/\//i.test(reciprocity)) {
  throw new Error('What you will do in return cannot contain a link: ' + reciprocity);
}

const config = {
  run_id: runId,
  started_at: new Date().toISOString(),
  tier: TIER,
  website: website,
  brand: brand,
  brand_domain: brandDomain,
  aliases: [brand, brand.replace(/\s+/g, ''), brandDomain.split('.')[0]]
    .map((s) => String(s).trim()).filter(Boolean)
    .filter((v, i, a) => a.map((x) => x.toLowerCase()).indexOf(v.toLowerCase()) === i),
  category: String(form.category || '').trim(),
  icp: String(form.icp || '').trim(),
  competitors: competitors,
  country: String(form.country || '').trim().toUpperCase() || 'US',
  sender_name: need(form.sender_name, 'Your name'),
  sender_role: need(form.sender_role, 'Your role'),
  // A verb phrase, not a sentence: the composer wraps it as "In return, I'd be happy to <this>."
  // It is the only promise this workflow makes to a stranger on the sender's behalf, so it comes
  // off the form and is never written, paraphrased or inferred by a model. Empty means the email
  // offers nothing back, which the gate then enforces in both directions.
  reciprocity: reciprocity,
  operator_email: need(form.results_email, 'Send results to'),
  spend_ceiling_usd: positive(form.spend_ceiling_usd, 'Spend ceiling (USD)'),
  followup_gap_days: positive(form.followup_gap_days, 'Days between follow-ups'),
  max_followups: positive(form.max_followups, 'Maximum follow-ups per prospect'),
  blocked_domains: blocked.length ? blocked : DEFAULT_BLOCKED,
  cost_usd: 0,
};

if (TIER === 'lite' && !config.category) {
  throw new Error('Lite has no model to read your site with, so "What you sell" is required');
}

config.scrapeBody = {
  url: website,
  formats: ['markdown', 'rawHtml'],
  onlyMainContent: false,
  stealth: false,
};
config.idemKey = idemKey(runId, 'web.scrape', config.scrapeBody);

return [{ json: config }];

