// The scrape either produced real page text or the run stops. Nothing downstream can profile a
// business, and in lite nothing can build a prompt, from an empty page.
const MIN_SITE_MARKDOWN_CHARS = 200;

const config = $('Normalize Onboarding Input').first().json;
const res = $input.first();

if (!httpOk(res)) {
  throw new Error('Could not read ' + config.website + ': AnyAPI web.scrape returned ' + httpStatus(res) + ' ' + httpErrorCode(res));
}
if (!httpFound(res)) {
