}

const data = httpData(res) || {};
const markdown = String(data.markdown || '');
if (markdown.length < MIN_SITE_MARKDOWN_CHARS) {
  throw new Error('Read ' + config.website + ' but only got ' + markdown.length + ' characters of text');
}

