function safeFirst(name) { const a = safeAll(name); return a.length ? a[0].json : null; }

// Every AnyAPI call is sent with fullResponse + neverError, so the workflow can tell an empty
// answer (200 found:false, charged) from a failure (>=400) instead of guessing from an error item.
