}

// Deterministic gate on the model's profile. The model may propose; this node decides.
// A buyer prompt only earns its place if it is the shape of question that makes an engine cite a
// third-party roundup. "What does Acme do" returns first-party pages and is worthless here.
const ALLOWED_STEMS = [/^best\s/i, /^top\s/i, /^what is the best\s/i, /^which\s/i, /^alternatives to\s/i, /^recommended\s/i];
const VS_SHAPE = /\svs\.?\s/i;

const config = $('Verify Your Website Was Read').first().json;
const raw = $input.first().json;
const parsed = raw && raw.output && typeof raw.output === 'object' ? raw.output : raw;

const asArray = (v) => (Array.isArray(v) ? v.map((s) => String(s).trim()).filter(Boolean) : []);
const category = String(parsed.category || config.category || '').trim();
if (!category) throw new Error('The model returned no category and none was supplied on the form');

const aliases = config.aliases
  .concat(asArray(parsed.aliases))
  .filter((v, i, a) => a.map((x) => x.toLowerCase()).indexOf(v.toLowerCase()) === i);

// Gate 1: the brand has to actually be on the site the model just read, or be the one you typed.
const haystack = (config.site_markdown + ' ' + config.site_raw_html).toLowerCase();
const brandOnSite = aliases.some((a) => haystack.indexOf(a.toLowerCase()) !== -1);
const brandIsYours = String(parsed.brand || '').trim().toLowerCase() === config.brand.toLowerCase();
if (!brandOnSite && !brandIsYours) {
  throw new Error('The model proposed a brand that is not on ' + config.website + ': ' + String(parsed.brand || ''));
}

// The data sources the site actually sells, validated against the page the same way the brand is,
// so the model cannot invent a market you are not in. This is what lets a prompt say "Reddit"
// instead of "data platform".
const dataSources = asArray(parsed.dataSources)
  .filter((s) => haystack.indexOf(s.toLowerCase()) !== -1);

const categoryWords = category.toLowerCase().split(/\s+/).filter((w) => w.length > 3);

// Strip the opening word and compare what is left, so "best X", "top X", "what is the best X" and
// "which X" collapse to one prompt. Measured: four of six prompts in one run were the same phrase
// with a different question word, discovery yielded 9 pitchable pages against the previous run's
// 59, and nothing downstream can recover width the prompt list never had.
const skeletonOf = (p) => normWs(p).toLowerCase()
  .replace(/^(what is the best|which|recommended|alternatives to|best|top)\s+/i, '')
  .replace(/[^a-z0-9 ]+/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// OWNER CHOICE. A prompt naming only the abstract category is the weakest kind - nobody searches
// for "data api aggregation platform" - so a couple are allowed as a floor and no more.
const MAX_CATEGORY_ONLY_PROMPTS = 2;

const rejected = [];
const seenSkeletons = new Set();
let categoryOnly = 0;
const buyerPrompts = asArray(parsed.buyerPrompts).filter((p) => {
  const shaped = ALLOWED_STEMS.some((re) => re.test(p)) || VS_SHAPE.test(p);
  if (!shaped) { rejected.push([p, 'not a recommendation-shaped question']); return false; }

  const lower = p.toLowerCase();
  // On topic now means: it names a data source this site really sells, OR names a competitor, OR
  // mentions the category. Demanding the category word was the actual bug - with a category of
  // "data api aggregation platform", the filter deleted "best Reddit scraping API" as off-topic.
  // The model was not being shallow, it was obeying a rule that only permitted shallow.
  const namesSource = dataSources.some((s) => lower.indexOf(s.toLowerCase()) !== -1);
  const namesRival = asArray(parsed.competitors).concat(config.competitors)
    .some((c) => c && lower.indexOf(String(c).toLowerCase()) !== -1);
  const namesCategory = categoryWords.length === 0 || categoryWords.some((w) => lower.indexOf(w) !== -1);
  if (!namesSource && !namesRival && !namesCategory) {
    rejected.push([p, 'names neither a data source you sell, a competitor, nor the category']);
    return false;
  }
  if (!namesSource && !namesRival) {
    categoryOnly += 1;
    if (categoryOnly > MAX_CATEGORY_ONLY_PROMPTS) {
      rejected.push([p, 'the category on its own, and ' + MAX_CATEGORY_ONLY_PROMPTS + ' of those are already in']);
      return false;
    }
  }

  const skeleton = skeletonOf(p);
  if (seenSkeletons.has(skeleton)) { rejected.push([p, 'the same question as one already kept, with a different opening word']); return false; }
  seenSkeletons.add(skeleton);

  // Naming yourself in the prompt biases the engine into citing you and destroys the measurement.
  const namesYou = aliases.some((a) => lower.indexOf(a.toLowerCase()) !== -1);
  if (namesYou) { rejected.push([p, 'names your own brand']); return false; }
  return true;
}).filter((v, i, a) => a.indexOf(v) === i);

if (buyerPrompts.length === 0) {
  throw new Error('No proposed buyer prompt survived the shape check. Rejected: ' + JSON.stringify(rejected));
}

const competitors = (asArray(parsed.competitors).length ? asArray(parsed.competitors) : config.competitors)
  .filter((c) => !aliases.some((a) => a.toLowerCase() === c.toLowerCase()));
if (competitors.length === 0) throw new Error('No competitors survived; add competitors on the form');

return [{
  json: Object.assign({}, config, {
    business: String(parsed.business || config.brand),
    category: category,
    icp: String(parsed.icp || config.icp || ''),
    value_prop: String(parsed.valueProp || parsed.value_prop || config.site_description || ''),
    buyer_prompts: buyerPrompts,
    data_sources: dataSources,
    rejected_prompts: rejected,
    aliases: aliases,
    competitors: competitors,
    profile_source: 'llm',
  }),
}];

const TIER = 'pro';

// --- shared helpers (inlined by the builder into every Code node that needs them) ---
const MULTI_TLD = ['co.uk', 'org.uk', 'ac.uk', 'gov.uk', 'com.au', 'net.au', 'org.au', 'co.nz', 'co.jp', 'co.kr', 'com.br', 'co.za', 'com.sg', 'co.in', 'com.mx', 'com.tr', 'co.il'];

function hostOf(u) {
  try { return new URL(String(u)).hostname.toLowerCase().replace(/^www\./, ''); } catch (e) { return ''; }
}

function registrable(hostOrUrl) {
  const raw = String(hostOrUrl || '');
  const h = /^https?:\/\//i.test(raw) ? hostOf(raw) : raw.toLowerCase().replace(/^www\./, '').split('/')[0];
  const parts = h.split('.').filter(Boolean);
  if (parts.length <= 2) return h;
  const last2 = parts.slice(-2).join('.');
  return MULTI_TLD.indexOf(last2) === -1 ? last2 : parts.slice(-3).join('.');
}

function normalizeUrl(u) {
  try {
    const url = new URL(String(u));
    if (url.protocol !== 'http:' && url.protocol !== 'https:') return '';
    url.hash = '';
    url.hostname = url.hostname.toLowerCase().replace(/^www\./, '');
    const drop = [];
    url.searchParams.forEach((_v, k) => { if (/^(utm_|fbclid|gclid|mc_|msclkid|igshid|ref$|source$)/i.test(k)) drop.push(k); });
    drop.forEach((k) => url.searchParams.delete(k));
    let s = url.toString().replace(/\?$/, '');
    if (url.pathname !== '/') s = s.replace(/\/$/, '');
    return s;
  } catch (e) { return ''; }
}

function normWs(s) { return String(s === null || s === undefined ? '' : s).replace(/\s+/g, ' ').trim(); }

function slugName(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ''); }

function canonical(v) {
  if (v === null || typeof v !== 'object') return JSON.stringify(v === undefined ? null : v);
  if (Array.isArray(v)) return '[' + v.map(canonical).join(',') + ']';
  return '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + canonical(v[k])).join(',') + '}';
}

// FNV-1a style 64-bit-ish hash rendered as 16 hex chars. Pure JS on purpose: n8n Code nodes
// cannot require('crypto') unless the instance sets NODE_FUNCTION_ALLOW_BUILTIN, and a giveaway
// workflow must not depend on an instance env var.
function stableHash(value) {
  const s = typeof value === 'string' ? value : canonical(value);
  let h1 = 0x811c9dc5;
  let h2 = 0x1000193;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 16777619) >>> 0;
    h2 = Math.imul(h2 + c, 2654435761) >>> 0;
  }
  return h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0');
}

// geo-<run_id>-<sku>-<bodyHash>. Computed here as a data field, never as an inline expression on
// the HTTP node: an inline expression is re-evaluated on retry, a data field is not.
function idemKey(runId, sku, body) { return 'geo-' + runId + '-' + sku + '-' + stableHash(body); }

function safeAll(name) { try { return $(name).all(); } catch (e) { return []; } }

function safeFirst(name) { const a = safeAll(name); return a.length ? a[0].json : null; }

// Every AnyAPI call is sent with fullResponse + neverError, so the workflow can tell an empty
// answer (200 found:false, charged) from a failure (>=400) instead of guessing from an error item.
function httpStatus(item) { const j = item && item.json ? item.json : item; return Number(j && j.statusCode) || 0; }
function httpBody(item) { const j = item && item.json ? item.json : item; return (j && j.body) || {}; }
function httpOk(item) { const s = httpStatus(item); return s >= 200 && s < 300; }
function httpCost(item) { return httpOk(item) ? Number(httpBody(item).costUsd || 0) : 0; }
function httpFound(item) { const o = httpBody(item).output || {}; return o.found === true; }
function httpData(item) { const o = httpBody(item).output || {}; return o.data || null; }
function httpErrorCode(item) {
  const b = httpBody(item);
  const e = b && b.error;
  if (e && typeof e === 'object') return String(e.code || e.message || 'error');
  if (typeof b === 'string') return b.slice(0, 200);
  return String((b && b.code) || httpStatus(item) || 'error');
}

// Builds one item per buyer prompt carrying a ready request body and idempotency key for each
// answer engine. This is the only place in the run with a large committed spend, so the ceiling is
// checked here before a single engine call goes out.
//
// All three engines now take the same body - just the prompt - because the SKUs that took a brand,
// a domain and a competitor list and returned a mentioned/cited verdict no longer exist. Working
// out whether you were named is now this workflow's job, and it happens in Verify Engine Answers
// against the answer text and the citation list. That is more work and a better measurement: the
// number comes with the text it was computed from, so the workbook can show its working.

// Verified customer prices, from the AnyAPI registry manifests. Ceilings where a SKU has lanes.
const PRICE_CHATGPT_SEARCH_USD = 0.0036;
const PRICE_PERPLEXITY_SEARCH_USD = 0.0018;
const PRICE_AI_OVERVIEW_USD = 0.0018;
const PRICE_GOOGLE_SEARCH_USD = 0.00126;
const PRICE_WEB_SCRAPE_USD = 0.0007;

const profile = $('Confirm Your Business Profile').first().json;
const prompts = profile.buyer_prompts;
const runId = profile.run_id;

const perPrompt = PRICE_CHATGPT_SEARCH_USD + PRICE_PERPLEXITY_SEARCH_USD + PRICE_AI_OVERVIEW_USD;
const fanout = prompts.length * perPrompt
  + prompts.length * PRICE_GOOGLE_SEARCH_USD
  + profile.competitors.length * PRICE_GOOGLE_SEARCH_USD;
const committed = Number(profile.cost_usd || 0) + fanout + PRICE_WEB_SCRAPE_USD;

if (committed > profile.spend_ceiling_usd) {
  throw new Error(
    'Stopping before the engine fan-out. ' + prompts.length + ' buyer prompts commit $' + fanout.toFixed(5)
    + ', which takes the run to $' + committed.toFixed(5) + ' against your $' + profile.spend_ceiling_usd
    + ' ceiling. Raise the ceiling or cut prompts.',
  );
}

return prompts.map((prompt, index) => {
  const body = { prompt: prompt };
  return {
    json: {
      run_id: runId,
      prompt_index: index,
      prompt: prompt,
      estimated_fanout_usd: Number(fanout.toFixed(6)),
      chatgptBody: body,
      chatgptIdem: idemKey(runId, 'chatgpt.search', body),
      perplexityBody: body,
      perplexityIdem: idemKey(runId, 'perplexity.search', body),
      aiOverviewBody: body,
      aiOverviewIdem: idemKey(runId, 'google.ai_overview', body),
    },
  };
});

