// Reads each engine node by name and pairs each response back to its prompt by position. The merge
// upstream is a barrier only: pairing a merged append stream back to its prompt is fragile, and
// pairing per engine node is one to one even when an engine errors out.
//
// The rule this node applies everywhere: 200 with found:false is data absence. Mark it, count it,
// move on. Status >= 400 is failure. Record it, and stop the run only when stopping is the honest
// outcome.
const ENGINES = [
  { key: 'chatgpt', node: 'AnyAPI Ask ChatGPT', sku: 'chatgpt.search' },
  { key: 'perplexity', node: 'AnyAPI Ask Perplexity', sku: 'perplexity.search' },
  { key: 'google_ai_overview', node: 'AnyAPI Ask Google AI Overview', sku: 'google.ai_overview' },
];
// 400 is a bad body, 402 is an empty wallet, 429 is a wall. None of those get quietly degraded.
// 409 is the interesting one, and it is two different things wearing one status code:
// idempotency_conflict and idempotency_needs_review mean the key formula is broken, which is a bug
// in this workflow and worth stopping for. idempotency_in_progress just means the identical call
// is still running somewhere, which is transient and costs you one prompt on one engine.
// Measured: a re-run inside the replay window hit in_progress and killed a run it should have
// finished.
const HARD_STOP_STATUSES = [400, 402, 429];
const HARD_STOP_CODES = ['idempotency_conflict', 'idempotency_needs_review'];

const profile = $('Confirm Your Business Profile').first().json;
const calls = $('Build Visibility Calls').all().map((i) => i.json);

// Whether you were named is now computed here rather than returned by the SKU. Word boundaries
// matter: without them "AnyAPI" matches inside "ManyAPIs" and every run reports a mention it never
// had. Aliases already include the brand, the brand with spaces removed, and the domain's first
// label, so this covers "AnyAPI", "Any API" and "getanyapi".
const aliasPattern = new RegExp(
  '(^|[^A-Za-z0-9])(' + profile.aliases
    .map((a) => String(a).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))
    .join('|') + ')($|[^A-Za-z0-9])',
  'i',
);
const namesYou = (text) => aliasPattern.test(String(text || ''));
const citesYou = (citations) => (Array.isArray(citations) ? citations : [])
  .some((c) => c && c.url && registrable(c.url) === profile.brand_domain);

const answers = [];
const perEngine = {};
let cost = 0;
let empty = 0;
let failed = 0;
let unsearched = 0;
const hardStops = [];

ENGINES.forEach((engine) => {
  const items = safeAll(engine.node);
  perEngine[engine.key] = { ok: 0, empty: 0, failed: 0 };
  items.forEach((item, index) => {
    const call = calls[index];
    if (!call) return;
    const status = httpStatus(item);
    cost += httpCost(item);
    if (!httpOk(item)) {
      failed += 1;
      perEngine[engine.key].failed += 1;
      const code = httpErrorCode(item);
      if (HARD_STOP_STATUSES.indexOf(status) !== -1 || HARD_STOP_CODES.indexOf(code) !== -1) {
        hardStops.push(engine.sku + ' returned ' + status + ' ' + code);
      }
      return;
    }
    if (!httpFound(item)) {
      empty += 1;
      perEngine[engine.key].empty += 1;
      answers.push({ prompt: call.prompt, engine: engine.key, found: false, data: null });
      return;
    }
    const data = httpData(item) || {};
    // chatgpt.search says whether it actually ran a web search for this prompt. An answer written
    // from the model's own memory is not evidence about who search engines recommend, so it is
    // marked and left out of the visibility denominator rather than counted as a miss. Counting it
    // would report "you were not mentioned" about an answer that never looked.
    const searched = data.webSearchTriggered === undefined ? true : data.webSearchTriggered === true;
    if (!searched) unsearched += 1;
    perEngine[engine.key].ok += 1;
    answers.push({
      prompt: call.prompt,
      engine: engine.key,
      found: true,
      searched: searched,
      data: data,
    });
  });
});

if (hardStops.length > 0) throw new Error('Stopping the run: ' + hardStops.join('; '));

const attempted = calls.length * ENGINES.length;
if (answers.filter((a) => a.found).length === 0) {
  throw new Error('No engine answered any prompt. ' + failed + ' of ' + attempted + ' calls failed and ' + empty + ' came back empty.');
}

// Your own measured visibility, which is the honest before-picture for the whole exercise. Every
// engine counts now: the AI Overview is what a searcher actually sees above the results, so leaving
// it out of the denominator understated the one surface with the most citations.
const visibility = answers
  .filter((a) => a.found && a.searched)
  .map((a) => {
    const text = String(a.data.answerMarkdown || a.data.answer || '');
    return {
      prompt: a.prompt,
      engine: a.engine,
      mentioned: namesYou(text),
      cited: citesYou(a.data.citations),
      citations: (Array.isArray(a.data.citations) ? a.data.citations : []).length,
    };
  });

return [{
  json: {
    run_id: profile.run_id,
    answers: answers,
    visibility: visibility,
    per_engine: perEngine,
    engine_calls: attempted,
    engine_calls_empty: empty,
    engine_calls_failed: failed,
    engine_calls_unsearched: unsearched,
    cost_usd: Number(profile.cost_usd || 0) + cost,
  },
}];

