// One set of names drives three later decisions: which pages are owned by somebody you cannot
// pitch, whether a page is genuinely a multi-vendor roundup, and whether the vendor a pitch names
// is real. Build it once, here.
//
// This used to scrape capitalised tokens out of the answer prose and call them brands, filtered by
// a hand-maintained list of about ninety stopwords. Every capitalised word not on that list became
// a rival, and the damage was not cosmetic - it was the roundup test, which asks whether a page
// names two different vendors. Measured on one run:
//
//   arxiv.org/abs/2608.09917   "vendors": Apify, Major, Pyktok, Community, Official, About,
//                              Whether, Other, Only, HTML, New, Features
//   getapp.ca/alternatives/... "vendors": Owner, Access, Cloudflare      <- a Cloudflare block page
//
// Both passed as multi-vendor roundups, both reached the paid contact step, and a preprint archive
// where no editor can add anything to a published paper became a prospect. The stopword list can
// never win that fight: it is a denylist against all of English.
//
// So names now come from two places that are actually about vendors, and prose is not one of them:
//
//   1. what you told us - your aliases and your competitors
//   2. the registrable domain of every page an engine cited
//
// A cited domain is a far better signal than a capitalised word: engines cite the sites that sell
// the thing and the sites that write about it, and the first group is exactly the set we need. It
// also degrades honestly. A missing brand costs a lead; an invented one costs an email telling an
// editor "you already cover Major".
const MIN_BRAND_TOKEN_CHARS = 3;

// Domains that are cited constantly and are nobody's product in any category.
const NOT_A_VENDOR = new Set([
  'github.com', 'reddit.com', 'quora.com', 'wikipedia.org', 'youtube.com', 'linkedin.com',
  'facebook.com', 'x.com', 'twitter.com', 'instagram.com', 'medium.com', 'news.ycombinator.com',
  'stackoverflow.com', 'arxiv.org', 'google.com', 'microsoft.com', 'apple.com', 'amazon.com',
  'cloudflare.com', 'npmjs.com', 'pypi.org', 'docs.rs', 'readthedocs.io', 'gitlab.com',
]);

const harvest = $input.first().json;
const profile = $('Confirm Your Business Profile').first().json;

const named = new Map();
const add = (name) => {
  const s = normWs(name);
  if (!s || s.length < MIN_BRAND_TOKEN_CHARS) return;
  const k = s.toLowerCase();
  if (!named.has(k)) named.set(k, s);
};

profile.aliases.forEach(add);
profile.competitors.forEach(add);

// A cited domain becomes a brand under the name it trades as: the first label of the domain, title
// cased, so scrapfly.io reads as Scrapfly. That is the name an editor would have written on the
// page, which is what the roundup test and the pitch gate both compare against.
harvest.answers.filter((a) => a.found && a.data).forEach((answer) => {
  (Array.isArray(answer.data.citations) ? answer.data.citations : []).forEach((c) => {
    if (!c || !c.url) return;
    const domain = registrable(c.url);
    if (!domain || NOT_A_VENDOR.has(domain)) return;
    const label = domain.split('.')[0];
    if (label.length < MIN_BRAND_TOKEN_CHARS) return;
    add(label.charAt(0).toUpperCase() + label.slice(1));
  });
});

const brandsNamed = Array.from(named.values());
const yours = profile.aliases.map((a) => a.toLowerCase());

// The two lists are NOT the same list, and conflating them is expensive in both directions.
//
//   brands_named - every vendor that might legitimately be named ON a page. Used by the roundup
//                  test and by the pitch gate's "is this vendor real" check. Wants to be generous:
//                  a name missing here costs a rejected draft.
//   rival_names  - the companies whose OWN pages you cannot pitch, because nobody adds a competitor
//                  to their own marketing. Used to throw pages away. Wants to be strict.
//
// Measured, by getting it wrong: feeding every cited domain into rival_names read 489 discovered
// pages as rival-owned and left 16. Every publisher that an engine cited became a rival, so the
// filter deleted exactly the pages the run exists to find.
//
// So rivals are only who you named on the form. Vendors you never listed are still caught, one band
// later and far more accurately, by the publisher filter reading their home page - which is a much
// better test than matching a domain against a name.
const rivalNames = profile.competitors
  .map((c) => normWs(c))
  .filter((c) => c && yours.indexOf(c.toLowerCase()) === -1);

return [{
  json: Object.assign({}, harvest, {
    brands_named: brandsNamed,
    rival_names: rivalNames,
  }),
}];

