  const parsed = item.json && item.json.output && typeof item.json.output === 'object' ? item.json.output : item.json;
  const list = Array.isArray(parsed && parsed.verdicts) ? parsed.verdicts : [];
  list.forEach((v) => {
    const d = registrable(String(v && v.domain ? v.domain : ''));
    const verdict = String(v && v.verdict ? v.verdict : '').toLowerCase();
    if (d && verdict) verdictOf.set(d, verdict);
  });
});

