const pages = $('Score And Rank Pitchable Pages').all().map((i) => i.json).filter((p) => p && p.page_url);

const kept = [];
const dropped = [];

pages.forEach((p) => {
  const domain = p.page_domain || registrable(p.page_url);
  const verdict = verdictOf.get(domain) || (unread.has(domain) ? 'unjudged' : 'unjudged');
