  const origin = 'https://' + p.page_domain;
  const candidates = CONTACT_PATHS.map((path) => origin + path);

  const shallow = Object.assign({}, p);
  delete shallow.raw_html;

  return {
    json: Object.assign(shallow, {
      author_name: cleanAuthor,
      author_first: first,
      author_last: last,
      contact_email: onDomainMailto,
      contact_source: onDomainMailto ? 'page_mailto' : '',
      page_mailtos: mailtos,
      contact_candidates: onDomainMailto ? [] : candidates,
    }),
  };
});

