const spent = Number($('Do We Still Need An Email?').first().json.cost_usd || config.cost_usd || 0);
const ceiling = Number(config.spend_ceiling_usd || 0);
const worstCase = PER_DOMAIN_LIMIT * PRICE_PER_RESULT_USD;

const claimed = new Set();
let reserved = 0;

return $input.all().map((item) => {
  const p = item.json;
  const email = String(p.contact_email || '').trim();
  const domain = p.page_domain || registrable(p.page_url || '');

  const no = (reason) => ({ json: Object.assign({}, p, { needs_domain_editor: false }, reason ? { domain_editor_skip_reason: reason } : {}) });

  if (!domain || p.status === 'rejected_publisher') return no('');
  if (email && !ROLE_INBOX.test(email)) return no('');

  // Everything below this line wants a lookup. Whether it gets one is a question about the domain
  // and the budget, not about the page.
  if (claimed.has(domain)) return no('another page on ' + domain + ' is already asking who edits it');
  if (ceiling > 0 && spent + reserved + worstCase > ceiling) return no('spend ceiling reached');

  claimed.add(domain);
  reserved += worstCase;

