// Reads the domain-editor lookup and decides who, if anyone, the email is now addressed to.
//
// The matching rule is the part worth reading. Where the page named an author, only that person is
// accepted out of the returned list: an email that quotes one writer's page and greets a different
// person is worse than no email at all. Where the page named nobody, the highest-confidence editor
// becomes the recipient, which is honest because the pitch says "the page", never "your article".
const calls = $('Build Domain Editor Calls').all().map((i) => i.json);

return $input.all().map((item, index) => {
  const p = calls[index];
  if (!p) return { json: { skipped: true } };
  if (!p.editor_lookup) return { json: p };

  if (!httpOk(item)) {
    return { json: Object.assign({}, p, { editor_error: httpErrorCode(item) }) };
  }

  const cost = httpCost(item);
  const data = httpData(item) || {};
  const contacts = Array.isArray(data.items) ? data.items : (Array.isArray(data.contacts) ? data.contacts : []);
  const usable = contacts.filter((c) => c && c.email);

  if (usable.length === 0) {
    return {
      json: Object.assign({}, p, {
        cost_usd: Number(p.cost_usd || 0) + cost,
        status: 'no_contact',
        reject_reason: 'no named editor is published for ' + p.page_domain,
      }),
    };
  }

  const wanted = normWs(p.author_name || '').toLowerCase();
  const byAuthor = wanted
    ? usable.find((c) => {
        const full = normWs((c.firstName || '') + ' ' + (c.lastName || '')).toLowerCase();
