  const chosen = wanted ? byAuthor : byRank;

  if (!chosen) {
    return {
      json: Object.assign({}, p, {
        cost_usd: Number(p.cost_usd || 0) + cost,
        status: 'no_contact',
        reject_reason: 'the page names ' + p.author_name + ' and no address was found for that person at ' + p.page_domain,
      }),
    };
  }

  const first = normWs(chosen.firstName || '');
  return {
    json: Object.assign({}, p, {
      cost_usd: Number(p.cost_usd || 0) + cost,
      contact_email: String(chosen.email),
      contact_source: 'domain_editor',
      contact_confidence: Number(chosen.confidence || 0),
      contact_title: normWs(chosen.position || ''),
      author_name: normWs(p.author_name || '') || normWs(first + ' ' + (chosen.lastName || '')),
      author_first: p.author_first || first,
    }),
  };
});

