const FREE_PROVIDERS = ['gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.co.uk', 'ymail.com', 'outlook.com', 'hotmail.com', 'hotmail.co.uk', 'live.com', 'msn.com', 'proton.me', 'protonmail.com', 'icloud.com', 'me.com', 'aol.com', 'gmx.com', 'mail.com', 'zoho.com', 'yandex.com'];
const BLOCKED_LOCAL_PARTS = ['abuse', 'postmaster', 'security', 'legal', 'privacy', 'dmca', 'noreply', 'no-reply', 'donotreply', 'do-not-reply', 'unsubscribe', 'webmaster'];
// OWNER CHOICE, and it is the opposite of ordinary outreach hygiene. For editorial outreach an
// editor@ or tips@ address is the correct address, not a role-address smell.
const ALLOWED_ROLE_PARTS = ['editor', 'editorial', 'hello', 'hi', 'team', 'press', 'tips', 'contact', 'news', 'info', 'submissions', 'partnerships'];

return $input.all().map((item) => {
  const p = item.json;
