  if (!email) {
    const reason = p.status === 'roundup_confirmed' ? (p.reject_reason || 'no contact address found on the page or its contact pages') : p.reject_reason;
    const status = p.status === 'roundup_confirmed' ? 'no_contact' : p.status;
    return { json: Object.assign({}, p, { status: status, reject_reason: reason, contact_email: '' }) };
  }

  const domain = registrable(email.split('@')[1] || '');
  const local = email.split('@')[0];
  const drop = (reason) => ({ json: Object.assign({}, p, { status: 'rejected_email', reject_reason: reason, contact_email: '', rejected_address_domain: domain }) });

  if (FREE_PROVIDERS.indexOf(domain) !== -1) return drop('address is on a free provider');
  if (domain !== p.page_domain) return drop('address domain ' + domain + ' does not match the page domain ' + p.page_domain);
  if (BLOCKED_LOCAL_PARTS.some((b) => local === b || local.indexOf(b) === 0)) return drop('address is a do-not-mail role account');
  if (local.indexOf('+') !== -1) return drop('address contains a plus tag');

  return {
    json: Object.assign({}, p, {
      contact_email: email,
      contact_is_role: ALLOWED_ROLE_PARTS.indexOf(local) !== -1,
    }),
  };
});

