// The email is assembled here, not written by a model. Both tiers build the same shape out of the
// same parts, so the only thing that differs between them is who writes the one line about this
// particular page.
//
// Why it is assembled at all: across runs 18 to 20 the model forgot the greeting, then the page
// link, then the quote, one per run, and each forgetting threw away every draft in that run. A part
// the code places is a part no model can drop.
//
// The shape is the one the outreach products in this market ship, because it is the shape that asks
// a stranger for something and gives them a reason to answer:
//
//   greeting
//   who I am, one line
//   why your page specifically
//   what you get back            <- omitted entirely when nothing was offered
//   one question
//   signature
//
// The verbatim quote is no longer printed in the email. It is still required, and still checked
// against the exact page text the writer was shown, because it is the proof the writer read the
// page. But a sentence lifted out of scraped markdown arrives carrying the page's own bullets and
// colons ("benefits: - AI tools can read page structures"), and an editor does not need their own
// sentence read back to them. The proof belongs in the workbook, not in the email.

const PITCH_TITLE_MAX = 70;
// Matches the gate's own SUBJECT_MIN_CHARS, so the composer never hands the gate a subject it is
// about to refuse.
const SUBJECT_FLOOR_CHARS = 15;

// Page titles usually carry the publisher after a pipe or a dash. Quoting that back at the
// publisher reads like a scraper wrote it, because one did.
const shortPageTitle = (title) => {
  const raw = normWs(title).split(/\s+[|]\s+|\s+[-]\s+/)[0];
  const cut = raw.length <= PITCH_TITLE_MAX ? raw : raw.slice(0, PITCH_TITLE_MAX).replace(/\s+\S*$/, '');
  return cut.replace(/[\s:,;.-]+$/, '');
};

// One sentence, not the homepage. The identity line is the first thing read, and a paragraph of
// product copy there is what makes a cold email read as a campaign. Measured on run 20: the pitch
// paragraph was three sentences of our own marketing before it said anything about their page.
//
// So it takes the first sentence and nothing else, and it does NOT then cut that sentence to a
// character count. Three separate drafts shipped with a truncated one - "...eliminating idle costs
// and.", "...billing from a.", "...from a prepaid USD wallet with no." - and each fix was a longer
// list of function words to strip off the end. That list is never finished, because the failure is
// the truncation, not the word it happens to stop on. The measured problem was three sentences; one
// sentence solves it exactly, whatever its length, and it is always grammatical because the operator
// wrote it that way.
const shortProp = (valueProp, category, aliases) => {
  const first = normWs(valueProp).split(/(?<=[.!?])\s+/)[0].replace(/[.!]+$/, '');
  const cut = first || ('a ' + normWs(category).replace(/[.!]+$/, ''));
  // It is spliced mid-sentence after "I'm Dana from Acme, ", so a capital letter there reads as a
  // sentence that lost its full stop. Measured on the first assembled run: "I'm Kevin Wang from
  // AnyAPI, One API key provides pay-per-request access..." - the value proposition was written as
  // its own sentence, which it no longer is. A brand name keeps its capital; nothing else does.
  const firstWord = cut.split(/\s+/)[0].replace(/[^A-Za-z0-9]/g, '');
  const isProperNoun = (aliases || []).some((a) => String(a).toLowerCase() === firstWord.toLowerCase());
  return isProperNoun ? cut : cut.charAt(0).toLowerCase() + cut.slice(1);
};

// The offer is a verb phrase supplied on the form and never written by a model, because it is a
// promise made to a stranger under the sender's name. No offer configured means no sentence at
// all: an invented one is the worst thing this workflow could send.
const reciprocitySentence = (offer) => {
  const raw = normWs(offer).replace(/^(and\s+)?in return[,\s]*/i, '').replace(/[.!]+$/, '');
  if (!raw) return '';
  const verb = raw.replace(/^(i(\s|')?d?\s+be\s+happy\s+to\s+|happy\s+to\s+|we(\s|')?d?\s+be\s+happy\s+to\s+)/i, '');
  return 'In return, I\'d be happy to ' + verb.charAt(0).toLowerCase() + verb.slice(1) + '.';
};

// parts.relevance is the only free text in the email: one clause saying why this page's readers
// would want the thing. Pro has a model write it off the page, lite builds it off the vendor the
// page already names.
const assemblePitch = (p, parts) => {
  const greeting = p.author_first ? 'Hi ' + p.author_first + ',' : 'Hi there,';
  const title = shortPageTitle(p.page_title);
  const relevance = normWs(parts.relevance).replace(/^[-\s]+/, '').replace(/[.!]+$/, '');

  const lines = [
    greeting,
    '',
    'I\'m ' + p.sender_name + ' from ' + p.brand + ', ' + shortProp(p.value_prop, p.category, p.aliases) + '.',
    '',
    'I came across your piece "' + title + '" and thought ' + p.brand
      + ' could be a relevant addition for your readers - ' + relevance + '.',
  ];

  const back = reciprocitySentence(p.reciprocity);
  if (back) lines.push('', back);

  lines.push(
    '',
    'Would this be something you would be open to?',
    '',
    'Best,',
    p.sender_name,
    p.sender_role + ' @ ' + p.brand,
    'https://' + p.brand_domain,
  );

