  // quote - so it is assembled here too. Measured on the first assembled run: the model returned a
  // six-character subject and the gate threw a complete, correct email away for it. The gate's
  // bounds stay where they are; this just stops a one-word subject reaching them.
  const subject = normWs(parts.subject || '');
