// Normalises the model's structured output onto the prospect record and assembles the email around
// it. It decides nothing: every claim the model made is checked by the next node against the exact
// text the model was shown.
//
// The model writes two things and only two: the subject, and one clause saying why this page's
// readers would want the product. Everything else - greeting, identity line, the offer back, the
// question, the signature - is placed by _pitch-skeleton.js. That split is the whole lesson of runs
// 18 to 20: three separate defects, each one the model forgetting a part it had been asked to
// assemble itself.
const prospects = $('Do We Have A Verified Contact?').all().map((i) => i.json);

const RELEVANCE_MIN_CHARS = 30;
const RELEVANCE_MAX_CHARS = 260;

return $input.all().map((item, index) => {
  const p = prospects[index];
  if (!p) return { json: { skipped: true } };
  const raw = item.json;
  const parsed = raw && raw.output && typeof raw.output === 'object' ? raw.output : raw;

  const subject = normWs(parsed.subject || '');
  const relevance = normWs(parsed.relevance || '');
  const quote = normWs(parsed.quotedSnippet || '');
  const vendor = normWs(parsed.vendorMentioned || '');

  if (!subject || !relevance || !quote || !vendor) {
    return { json: Object.assign({}, p, { pitch: null, pitch_source: 'model', pitch_missing_reason: 'the model returned an incomplete pitch object' }) };
  }

  // The relevance clause is dropped into a sentence this code owns, so a clause that is really a
  // whole email, or really nothing, breaks the sentence rather than the gate. Caught here where the
  // reason is readable instead of downstream as a length failure.
  if (relevance.length < RELEVANCE_MIN_CHARS || relevance.length > RELEVANCE_MAX_CHARS) {
    return { json: Object.assign({}, p, { pitch: null, pitch_source: 'model', pitch_missing_reason: 'the relevance clause was ' + relevance.length + ' characters, outside ' + RELEVANCE_MIN_CHARS + '-' + RELEVANCE_MAX_CHARS }) };
  }

  const built = assemblePitch(p, { relevance: relevance, subject: subject });

  return {
    json: Object.assign({}, p, {
      pitch_source: 'model',
      pitch: {
        subject: built.subject,
        greeting: built.greeting,
        body: built.body,
        quotedSnippet: quote,
        vendorMentioned: vendor,
        whyRelevant: relevance,
        pageTitleShort: built.page_title_short,
        reciprocityLine: built.reciprocity_line,
      },
    }),
  };
});

