// The hard gate. Thirteen deterministic checks, all of them run, and a draft is only created when
// every one passes. Nothing here asks a model whether the email is fine.
// OWNER CHOICE: the four length bounds. The body bounds are tighter than they were, because the
// email is now assembled from a fixed skeleton: an assembled email that lands outside them means a
// part is missing or the one free clause ran away, and both are worth refusing.
const SUBJECT_MIN_CHARS = 15;
const SUBJECT_MAX_CHARS = 120;
const BODY_MIN_CHARS = 300;
const BODY_MAX_CHARS = 1400;
const QUOTE_MIN_CHARS = 40;

const brands = $('Name Every Brand In The Answers').first().json;
const profile = $('Confirm Your Business Profile').first().json;
const brandsNamedLower = brands.brands_named.map((b) => b.toLowerCase());

const FAKE_HISTORY = /as (we )?discussed|following up on our (call|chat)|per our conversation|you mentioned|last time we spoke|great (call|chat)|as promised|thanks for (your time|the call)/i;
const PLACEHOLDER = /\[[A-Z_ ]{2,}\]|\{\{|<[A-Z_]{2,}>|\bTODO\b|\bXXX\b|lorem ipsum/i;
// No /i flag on purpose. With it, [A-Z] also matches lowercase, so "Hi there," reads as a
// greeting to a person called There and every anonymous draft gets rejected. Measured: 8 of them.
const NAMED_GREETING = /^(?:[Hh]i|[Hh]ey|[Hh]ello|[Dd]ear)\s+[A-Z][a-z]+/m;

return $input.all().map((item) => {
  const p = item.json;
  const failures = [];
  const pitch = p.pitch;

  if (!pitch) {
    return { json: Object.assign({}, p, { status: 'rejected_verify', reject_reason: p.pitch_missing_reason || 'no pitch was composed', verify_failures: ['no pitch'], draft_ready: false }) };
  }

  const subject = pitch.subject;
  const body = pitch.body;
  const quote = pitch.quotedSnippet;
  const context = normWs(p.pitch_context);

  // 1. The writer really read the page: it had to copy a real sentence out of the same text it was
  // shown, and that sentence is checked character for character. The quote is not printed in the
  // email any more, so this is now purely the proof of reading - which is what it was always for.
  // It is carried to the workbook so the operator can see what grounded each draft.
  if (quote.length < QUOTE_MIN_CHARS) failures.push('quote is shorter than ' + QUOTE_MIN_CHARS + ' characters');
  else if (context.indexOf(normWs(quote)) === -1) failures.push('quoted snippet is not on the page');

  // 2. The email names the page it is about. This replaces the old "the body contains the quote":
  // an email that cannot name their piece has no business asking them to change it, and the title
  // is the one thing about the page that is always clean, unlike a sentence lifted out of markdown.
  const titleShort = normWs(pitch.pageTitleShort || '');
  if (!titleShort) failures.push('the email does not carry a page title');
  else if (normWs(body).indexOf(titleShort) === -1) failures.push('the email never names the page it is about');

  // 3. The vendor named is a brand the engines named and is on the page.
  //
  // "On the page" means the whole page, not the excerpt. vendors_on_page is built in
  // verify-the-page-is-a-real-roundup.js by matching each rival against the full page markdown on
  // word boundaries, so a name in that list is proven to be on the page - stronger evidence than a
  // substring search of the first 6000 characters, not weaker.
  //
  // Checking the excerpt instead cost 10 of 17 pitches in one run, every one of them for a vendor
  // that really was on the page. The prompt hands the model this exact list as "Vendors already on
  // the page", so the gate was punishing it for the answer it was given. The quote in check 1 still
  // checks against the excerpt, because that claim IS about the text the writer was shown.
  const vendorLower = String(pitch.vendorMentioned || '').toLowerCase();
  const onPage = (p.vendors_on_page || []).some((v) => String(v).toLowerCase() === vendorLower)
    || context.toLowerCase().indexOf(vendorLower) !== -1;
  if (!vendorLower || brandsNamedLower.indexOf(vendorLower) === -1) failures.push('vendor named is not one of the brands the engines named');
  else if (!onPage) failures.push('vendor named is not on the page');

  // 4. No invented links. Only the page itself and your own domain may appear, with or without a
  // scheme in front of it. Matching only https?:// let a model write "AnyAPI (anyapi.com)" and pass
  // the whole gate: a bare domain reads to the recipient exactly like a link, and that one is a
  // different company. Measured in the first pro run, on a draft that was otherwise clean, and it
  // has since blocked anyapi.com, anyapi.dev and an invented Serper.dev.
  const urls = (subject + ' ' + body).match(/https?:\/\/[^\s<>")\]]+/g) || [];
  const strayUrl = urls.find((u) => {
    const clean = u.replace(/[.,;:)]+$/, '');
    return normalizeUrl(clean) !== p.page_url && registrable(clean) !== p.brand_domain;
  });
  if (strayUrl) failures.push('email contains a URL that is neither the page nor your site: ' + strayUrl);

  // Real links and email addresses come out first so only bare domains are left. The TLD list is
  // explicit rather than a catch-all so "Node.js" and "etc." are not read as domains.
  const BARE_TLD = 'com|net|org|io|ai|dev|co|app|xyz|me|info|biz|uk|us|de|fr|es|it|nl|se|no|ca|au|in|jp';
  const prose = (subject + ' ' + body)
    .replace(/https?:\/\/[^\s<>")\]]+/g, ' ')
    .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+/g, ' ');
  const allowed = [p.brand_domain, registrable(p.page_url), registrable(String(p.contact_email || '').split('@')[1] || '')]
    .filter(Boolean);
  const bare = prose.match(new RegExp('\\b(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\\.)+(?:' + BARE_TLD + ')\\b', 'gi')) || [];
  const strayDomain = bare.find((d) => allowed.indexOf(registrable(d)) === -1);
  if (strayDomain) failures.push('email names a domain that is neither the page nor your site: ' + strayDomain);

  // 5. The page URL appears at most once. It used to be required exactly once, which is what forced
  // the bare link on its own line at the end of every draft. An editor knows their own article, and
  // the email names it by title in check 2; the URL is on the prospect record for us, not for them.
  const pageUrlCount = urls.filter((u) => normalizeUrl(u.replace(/[.,;:)]+$/, '')) === p.page_url).length;
  if (pageUrlCount > 1) failures.push('the page URL appears ' + pageUrlCount + ' times, expected at most once');

  // 6. The greeting matches what we actually know about the author.
  if (p.author_first) {
    if (body.indexOf(p.author_first) === -1) failures.push('the author has a first name and the email does not use it');
  } else if (NAMED_GREETING.test(body)) {
    failures.push('the email greets a person by name and no author name was found');
  }

  // 7. No invented relationship.
  if (FAKE_HISTORY.test(body)) failures.push('the email implies a relationship that does not exist');

  // 8. No faked thread.
  if (subject.indexOf('\n') !== -1) failures.push('subject is more than one line');
  if (/^(re|fwd):/i.test(subject)) failures.push('subject fakes a reply');

  // 9. No placeholders left in.
  if (PLACEHOLDER.test(subject + ' ' + body)) failures.push('email still contains a placeholder');

  // 10. It is a pitch for inclusion, so it has to name you.
  const namesYou = profile.aliases.some((a) => (subject + ' ' + body).toLowerCase().indexOf(a.toLowerCase()) !== -1);
  if (!namesYou) failures.push('the email never names your brand');

  // 11. The recipient is on the page's own domain.
  const recipientDomain = registrable(String(p.contact_email || '').split('@')[1] || '');
  if (!recipientDomain || recipientDomain !== p.page_domain) failures.push('recipient domain does not match the page domain');

  // 12. Length bounds.
  if (subject.length < SUBJECT_MIN_CHARS || subject.length > SUBJECT_MAX_CHARS) failures.push('subject length ' + subject.length + ' is outside ' + SUBJECT_MIN_CHARS + '-' + SUBJECT_MAX_CHARS);
  if (body.length < BODY_MIN_CHARS || body.length > BODY_MAX_CHARS) failures.push('body length ' + body.length + ' is outside ' + BODY_MIN_CHARS + '-' + BODY_MAX_CHARS);

  // 13. The email promises back exactly what was configured on the form, or promises nothing.
  // The offer is the one sentence in here that commits the sender to doing something for a
  // stranger, so it is never model-written and never inferred: it is placed verbatim from the form
  // by the composer, and an email carrying an offer nobody configured is refused outright.
  const offerLine = normWs(pitch.reciprocityLine || '');
  const offered = normWs(p.reciprocity || '');
  const offerCount = offerLine ? normWs(body).split(offerLine).length - 1 : 0;
  if (offered && offerCount !== 1) failures.push('the offer you configured appears ' + offerCount + ' times, expected exactly once');
  if (!offered && /\bin return\b/i.test(body)) failures.push('the email offers something back and nothing was configured on the form');

  if (failures.length > 0) {
    return { json: Object.assign({}, p, { status: 'rejected_verify', reject_reason: failures[0], verify_failures: failures, draft_ready: false }) };
  }

  return {
    json: Object.assign({}, p, {
      status: 'verified',
      reject_reason: '',
      verify_failures: [],
      draft_ready: true,
      subject: subject,
      body: body,
      quoted_snippet: quote,
    }),
  };
});

