  + '</tr>').join('');

record.html = [
  '<div style="' + FONT + 'max-width:1040px;color:#111827;">',
  '<h2 style="margin:0 0 4px;font-size:20px;">' + record.drafts_created + ' draft' + (record.drafts_created === 1 ? ' is' : 's are') + ' waiting in your Gmail</h2>',
  '<p style="margin:0 0 18px;color:#6b7280;font-size:14px;">Nothing was sent. Open Gmail, read them, press send on the ones you like.</p>',
  '<table cellpadding="0" cellspacing="0" style="margin-bottom:20px;"><tr>',
  stat(record.citations_harvested, 'pages the engines cited'),
  stat(record.pages_after_ownership_filter, 'you could actually pitch'),
  stat(record.visibility_cited + ' / ' + record.visibility_checks, 'prompt and engine pairs citing you'),
