  const b = httpBody(item);
  const e = b && b.error;
  if (e && typeof e === 'object') return String(e.code || e.message || 'error');
  if (typeof b === 'string') return b.slice(0, 200);
  return String((b && b.code) || httpStatus(item) || 'error');
}

// The Data Table gets the reason before the execution is allowed to die.
const record = $('Build Run Record').first().json;
const failure = $input.first().json || {};
const message = failure.error && failure.error.message ? failure.error.message : (failure.message || 'Gmail refused the summary email');

return [{
  json: Object.assign({}, record, {
    status: 'failed',
    delivery_id: '',
    failure_reason: String(message).slice(0, 500),
  }),
}];
